<?php require_once __DIR__.'/../includes/bootstrap.php';$u=require_role('filmmaker');$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM casting_calls WHERE id=? AND user_id=?');$s->execute([$id,$u['id']]);$job=$s->fetch();if(!$job){http_response_code(404);exit('Casting call not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=(int)($_POST['application_id']??0);$status=$_POST['status']??'';if(in_array($status,['shortlisted','rejected','selected'],true)){db()->prepare('UPDATE applications SET status=? WHERE id=? AND casting_id=?')->execute([$status,$a,$id]);}}$s=db()->prepare('SELECT a.*,u.name,u.email,p.city,p.age,p.skills,p.bio,p.portfolio_url FROM applications a JOIN users u ON u.id=a.talent_id LEFT JOIN talent_profiles p ON p.user_id=u.id WHERE a.casting_id=? ORDER BY a.created_at DESC');$s->execute([$id]);$apps=$s->fetchAll();$pageTitle='Applicants · '.$job['title'];require __DIR__.'/../includes/header.php';?><main class="page-wrap"><div class="container"><div class="eyebrow dark">TALENT PIPELINE</div><h1 class="page-title"><?=e($job['title'])?></h1><?php if(!$apps):?><div class="empty-state">No applications yet. Share your casting call to reach more talent.</div><?php else:?><div class="cards-list"><?php foreach($apps as $a):?><article class="job-card"><div class="job-meta"><span><?=e($a['city']??'Location not added')?></span><span class="status"><?=e($a['status'])?></span></div><h3><?=e($a['name'])?></h3><p><?=e($a['age']??'Age not added')?> · <?=e($a['skills']??'')?></p><p><?=nl2br(e($a['bio']??''))?></p><p><a class="text-link" href="mailto:<?=e($a['email'])?>"><?=e($a['email'])?></a><?php if($a['portfolio_url']):?> · <a class="text-link" target="_blank" rel="noopener" href="<?=e($a['portfolio_url'])?>">Portfolio ↗</a><?php endif;?></p><p><?=e($a['note'])?></p><form method="post" class="job-actions"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="application_id" value="<?=$a['id']?>"><select name="status"><option value="submitted">Submitted</option><option value="shortlisted">Shortlisted</option><option value="selected">Selected</option><option value="rejected">Rejected</option></select><button class="btn btn-dark">Update</button></form></article><?php endforeach;?></div><?php endif;?></div></main><?php require __DIR__.'/../includes/footer.php'; ?>